blocks.text:
.container {
  width: 200px;
  height: 250px;

  perspective: 600px;
}

.card {
  width: 100%;
  height: 100%;
  position:
  relative;
  transition: transform 1s;
  transform-style:
  preserve-3d;
}

.face {
  position: absolute;
  height: 100%;
  width:
  100%;
  backface-visibility: hidden;
  text-align: center;

  }

.front {
  background: green;
}

.back {

  background: red;
  transform: rotateY(180deg);
}

.container:hover .card {
  transform: rotateY(180deg);
}

